ion: relative;\n  display: grid;\n  width: 100%;\n  height: 100%;\n  padding: 24px;\n  overflow: auto;\n  place-items: center;\n  color: var(--text);\n  font-family:\n    Inter,\n    'Noto Sans SC',\n    'Microsoft YaHei',\n    system-ui,\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    sans-serif;\n}\n\n.backdrop {\n  position: fixed;\n  z-index: 0;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  padding: 0;\n  background: rgb(3 5 8 / 78%);\n  border: 0;\n  backdrop-filter: blur(9px);\n  cursor: default;\n}\n\n.character-detail-layer {\n  position: fixed;\n  z-index: 3;\n  inset: 0;\n  display: grid;\n  padding: 24px;\n  overflow: auto;\n  place-items: center;\n  background: rgb(3 5 8 / 86%);\n  backdrop-filter: blur(12px);\n}\n\n.character-detail-dialog {\n  display: flex;\n  width: min(1240px, 100%);\n  max-height: min(900px, calc(100vh - 48px));\n  min-height: 0;\n  overflow: hidden;\n  flex-direction: column;\n  background: radial-gradient(circle at 0 0, rgb(119 214 199 / 9%), transparent 30rem), var(--bg);\n  border: 1px solid var(--border-strong);\n  border-radius: 18px;\n  outline: none;\n  box-shadow: 0 30px 90px rgb(0 0 0 / 62%);\n}\n\n.character-detail-header {\n  display: flex;\n  padding: 20px 24px;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 20px;\n  background: rgb(19 23 32 / 96%);\n  border-bottom: 1px solid var(--border);\n}\n\n.character-detail-header h2,\n.character-detail-header p {\n  margin: 0;\n}\n\n.character-detail-header h2 {\n  margin-top: 7px;\n  font-size: clamp(24px, 3.5vw, 36px);\n}\n\n.character-detail-header p {\n  margin-top: 6px;\n  color: var(--text-muted);\n  font-size: 11px;\n}\n\n.character-detail-status {\n  display: inline-flex;\n  padding: 4px 8px;\n  color: var(--success);\n  background: rgb(120 213 156 / 10%);\n  border: 1px solid rgb(120 213 156 / 25%);\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 800;\n}\n\n.character-detail-status.disabled {\n  color: var(--text-muted);\n  background: rgb(127 139 160 / 10%);\n  border-color: rgb(127 139 160 / 24%);\n}\n\n.character-detail-body {\n  display: grid;\n  min-height: 0;\n  overflow: hidden;\n  grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);\n}\n\n.character-detail-gallery,\n.character-detail-content {\n  min-height: 0;\n  padding: 20px;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n}\n\n.character-detail-content {\n  background: rgb(19 23 32 / 70%);\n  border-left: 1px solid var(--border);\n}\n\n.character-detail-section-heading {\n  display: flex;\n  margin-bottom: 14px;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.character-detail-section-heading span {\n  color: var(--primary);\n  font-size: 9px;\n  font-weight: 900;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n}\n\n.character-detail-section-heading h3 {\n  margin: 3px 0 0;\n  font-size: 18px;\n}\n\n.character-detail-section-heading b {\n  color: var(--text-muted);\n  font-size: 10px;\n}\n\n.character-detail-gallery-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n  gap: 12px;\n}\n\n.character-detail-gallery-grid figure {\n  min-width: 0;\n  margin: 0;\n  overflow: hidden;\n  background: var(--surface-raised);\n  border: 1px solid var(--border);\n  border-radius: 12px;\n}\n\n.character-detail-media {\n  display: grid;\n  aspect-ratio: 3 / 4;\n  overflow: hidden;\n  place-items: center;\n  color: var(--text-muted);\n  background: var(--surface-soft);\n  font-size: 11px;\n}\n\n.character-detail-media img,\n.character-detail-media video {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.character-detail-gallery-grid figcaption {\n  display: flex;\n  padding: 9px 10px;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.character-detail-gallery-grid figcaption strong {\n  overflow: hidden;\n  font-size: 11px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.chara